using System.ComponentModel;
using System.Net;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Build the IChatClient via MEAI abstraction ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .AsChatClient(modelId);

// --- Instantiate the tools ---
var researchTools = new ResearchTools();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(researchTools.SearchWebAsync),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

// --- Create the ChatClientAgent ---
var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI agent that researches topics by searching the web and taking notes.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = tools,
        },
    });

// --- Wrap with a LoopAgent for multi-step agentic execution ---
var loopAgent = new LoopAgent(
    agent,
    new CompletionMarkerLoopEvaluator("[RESEARCH_COMPLETE]"),
    new LoopAgentOptions { MaxIterations = 10 });

// --- Get the research topic ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

var prompt = $"""
    You are a research assistant. Your goal is to thoroughly research the following topic
    and produce a well-organized summary.

    **Topic:** {topic}

    **Instructions:**
    1. Use the SearchWeb tool to find information about the topic. Make multiple searches
       with different queries to get a comprehensive view.
    2. Use the SaveNote tool to record important findings as you go.
    3. Use the GetNotes tool to review everything you've collected.
    4. After gathering enough information (at least 3 searches), review your notes
       and produce a final summary.
    5. End your final message with the marker [RESEARCH_COMPLETE]

    Begin your research now.
    """;

Console.WriteLine($"\nResearching: {topic}\n");
Console.WriteLine(new string('─', 60));

// --- Run the agent with streaming output ---
var session = await agent.CreateSessionAsync();

await foreach (var update in loopAgent.RunStreamingAsync(prompt, session))
{
    if (!string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine();
Console.WriteLine(new string('─', 60));
Console.WriteLine($"\nResearch complete. {researchTools.NoteCount} note(s) saved during research.");

// =============================================================================
// Tools
// =============================================================================

/// <summary>Provides web search and note-taking tools for the research agent.</summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    public int NoteCount => _notes.Count;

    [Description("Searches the web for a given query and returns a summary of results. " +
                 "Use this to find information about a topic.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"\n  🔍 Searching: \"{query}\"");

        try
        {
            // Use Wikipedia API as a free, reliable search source
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search" +
                      $"&srsearch={encoded}&srlimit=3&format=json&utf8=1";

            var response = await _httpClient.GetStringAsync(url, cancellationToken);

            // Also fetch a short extract for the top result
            var extractUrl = $"https://en.wikipedia.org/w/api.php?action=query" +
                             $"&titles={encoded}&prop=extracts&exintro=1&explaintext=1" +
                             $"&exsectionformat=plain&format=json&utf8=1&redirects=1";

            var extractResponse = await _httpClient.GetStringAsync(extractUrl, cancellationToken);

            Console.WriteLine("  ✅ Search returned results.");

            return $"Search results for \"{query}\":\n\n" +
                   $"Wikipedia search API response:\n{response}\n\n" +
                   $"Wikipedia extract:\n{extractResponse}";
        }
        catch (Exception ex)
        {
            Console.WriteLine($"  ⚠️  Search failed: {ex.Message}");
            return $"Search failed for \"{query}\": {ex.Message}. Try a different query.";
        }
    }

    [Description("Saves a research note for later reference. Use this to record " +
                 "important findings during research.")]
    public string SaveNote(
        [Description("A concise note summarizing a key finding")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"\n  📝 Note #{_notes.Count} saved.");
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieves all research notes saved so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var formatted = string.Join("\n",
            _notes.Select((n, i) => $"  [{i + 1}] {n}"));

        Console.WriteLine($"\n  📋 Reviewing {_notes.Count} note(s).");
        return $"All saved notes ({_notes.Count} total):\n{formatted}";
    }
}

