1. using System.ComponentModel;
2. using System.Net;
3. using Microsoft.Agents.AI;
4. using Microsoft.Extensions.AI;
5. using OpenAI;
6. 
7. // --- Configuration ---
8. var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
9.     ?? throw new InvalidOperationException(
10.         "Set the OPENAI_API_KEY environment variable before running.");
11. 
12. const string modelId = "gpt-4o-mini-2024-07-18";
13. 
14. // --- Build the IChatClient via MEAI abstraction ---
15. IChatClient chatClient = new OpenAIClient(apiKey)
16.     .GetChatClient(modelId)
17.     .AsIChatClient();
18. 
19. // --- Instantiate the tools ---
20. var researchTools = new ResearchTools();
21. 
22. var tools = new List<AITool>
23. {
24.     AIFunctionFactory.Create(researchTools.SearchWebAsync),
25.     AIFunctionFactory.Create(researchTools.SaveNote),
26.     AIFunctionFactory.Create(researchTools.GetNotes),
27. };
28. 
29. // --- Create the ChatClientAgent ---
30. var agent = new ChatClientAgent(
31.     chatClient,
32.     new ChatClientAgentOptions
33.     {
34.         Name = "ResearchAgent",
35.         Description = "An AI agent that researches topics by searching the web and taking notes.",
36.         ChatOptions = new ChatOptions
37.         {
38.             Temperature = 0f,
39.             MaxOutputTokens = 2048,
40.             Tools = tools,
41.         },
42.     });
43. 
44. // --- Wrap with a LoopAgent for multi-step agentic execution ---
45. var loopAgent = new LoopAgent(
46.     agent,
47.     new CompletionMarkerLoopEvaluator("[RESEARCH_COMPLETE]"),
48.     new LoopAgentOptions { MaxIterations = 10 });
49. 
50. // --- Get the research topic ---
51. Console.Write("Enter a research topic: ");
52. var topic = Console.ReadLine()?.Trim();
53. if (string.IsNullOrWhiteSpace(topic))
54. {
55.     Console.WriteLine("No topic provided. Exiting.");
56.     return;
57. }
58. 
59. var prompt = $"""
60.     You are a research assistant. Your goal is to thoroughly research the following topic
61.     and produce a well-organized summary.
62. 
63.     **Topic:** {topic}
64. 
65.     **Instructions:**
66.     1. Use the SearchWeb tool to find information about the topic. Make multiple searches
67.        with different queries to get a comprehensive view.
68.     2. Use the SaveNote tool to record important findings as you go.
69.     3. Use the GetNotes tool to review everything you've collected.
70.     4. After gathering enough information (at least 3 searches), review your notes
71.        and produce a final summary.
72.     5. End your final message with the marker [RESEARCH_COMPLETE]
73. 
74.     Begin your research now.
75.     """;
76. 
77. Console.WriteLine($"\nResearching: {topic}\n");
78. Console.WriteLine(new string('─', 60));
79. 
80. // --- Run the agent with streaming output ---
81. var session = await agent.CreateSessionAsync();
82. 
83. await foreach (var update in loopAgent.RunStreamingAsync(prompt, session))
84. {
85.     if (!string.IsNullOrEmpty(update.Text))
86.     {
87.         Console.Write(update.Text);
88.     }
89. }
90. 
91. Console.WriteLine();
92. Console.WriteLine(new string('─', 60));
93. Console.WriteLine($"\nResearch complete. {researchTools.NoteCount} note(s) saved during research.");
94. 
