99. /// <summary>Provides web search and note-taking tools for the research agent.</summary>
100. sealed class ResearchTools
101. {
102.     private readonly List<string> _notes = [];
103.     private readonly HttpClient _httpClient = new();
104. 
105.     public int NoteCount => _notes.Count;
106. 
107.     [Description("Searches the web for a given query and returns a summary of results. " +
108.                  "Use this to find information about a topic.")]
109.     public async Task<string> SearchWebAsync(
110.         [Description("The search query string")] string query,
111.         CancellationToken cancellationToken = default)
112.     {
113.         Console.WriteLine($"\n  🔍 Searching: \"{query}\"");
114. 
115.         try
116.         {
117.             // Use Wikipedia API as a free, reliable search source
118.             var encoded = WebUtility.UrlEncode(query);
119.             var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search" +
120.                       $"&srsearch={encoded}&srlimit=3&format=json&utf8=1";
121. 
122.             var response = await _httpClient.GetStringAsync(url, cancellationToken);
123. 
124.             // Also fetch a short extract for the top result
125.             var extractUrl = $"https://en.wikipedia.org/w/api.php?action=query" +
126.                              $"&titles={encoded}&prop=extracts&exintro=1&explaintext=1" +
127.                              $"&exsectionformat=plain&format=json&utf8=1&redirects=1";
128. 
129.             var extractResponse = await _httpClient.GetStringAsync(extractUrl, cancellationToken);
130. 
131.             Console.WriteLine("  ✅ Search returned results.");
132. 
133.             return $"Search results for \"{query}\":\n\n" +
134.                    $"Wikipedia search API response:\n{response}\n\n" +
135.                    $"Wikipedia extract:\n{extractResponse}";
136.         }
137.         catch (Exception ex)
138.         {
139.             Console.WriteLine($"  ⚠️  Search failed: {ex.Message}");
140.             return $"Search failed for \"{query}\": {ex.Message}. Try a different query.";
141.         }
142.     }
143. 
144.     [Description("Saves a research note for later reference. Use this to record " +
145.                  "important findings during research.")]
146.     public string SaveNote(
147.         [Description("A concise note summarizing a key finding")] string note)
148.     {
149.         _notes.Add(note);
150.         Console.WriteLine($"\n  📝 Note #{_notes.Count} saved.");
151.         return $"Note #{_notes.Count} saved successfully.";
152.     }
153. 
154.     [Description("Retrieves all research notes saved so far.")]
155.     public string GetNotes()
156.     {
157.         if (_notes.Count == 0)
158.         {
159.             return "No notes saved yet.";
160.         }
161. 
162.         var formatted = string.Join("\n",
163.             _notes.Select((n, i) => $"  [{i + 1}] {n}"));
164. 
165.         Console.WriteLine($"\n  📋 Reviewing {_notes.Count} note(s).");
166.         return $"All saved notes ({_notes.Count} total):\n{formatted}";
167.     }
168. }
