     .GetChatClient(modelId)
     .AsIChatClient();

 // --- Instantiate the tools ---
 var researchTools = new ResearchTools();

 var tools = new List<AITool>
 {
     AIFunctionFactory.Create(researchTools.SearchWebAsync),
     AIFunctionFactory.Create(researchTools.SaveNote),
     AIFunctionFactory.Create(researchTools.GetNotes),
 };

 // --- Create the ChatClientAgent ---
 var agent = new ChatClientAgent(
     chatClient,
     new ChatClientAgentOptions
     {
         Name = "ResearchAgent",
         Description = "An AI agent that researches topics by searching the web and taking notes.",
         ChatOptions = new ChatOptions
         {
             Temperature = 0f,
             MaxOutputTokens = 2048,
             Tools = tools,
         },
     });

 // --- Wrap with a LoopAgent for multi-step agentic execution ---
 var loopAgent = new LoopAgent(
     agent,
     new CompletionMarkerLoopEvaluator("[RESEARCH_COMPLETE]"),
     new LoopAgentOptions { MaxIterations = 10 });

 // --- Get the research topic ---
 Console.Write("Enter a research topic: ");
 var topic = Console.ReadLine()?.Trim();
 if (string.IsNullOrWhiteSpace(topic))
 {
     Console.WriteLine("No topic provided. Exiting.");
     return;
 }

 var prompt = $"""
     You are a research assistant. Your goal is to thoroughly research the following topic
     and produce a well-organized summary.

     **Topic:** {topic}

     **Instructions:**
     1. Use the SearchWeb tool to find information about the topic. Make multiple searches
        with different queries to get a comprehensive view.
     2. Use the SaveNote tool to record important findings as you go.
     3. Use the GetNotes tool to review everything you've collected.
     4. After gathering enough information (at least 3 searches), review your notes
        and produce a final summary.
     5. End your final message with the marker [RESEARCH_COMPLETE]

     Begin your research now.
     """;

